x=y=99;setup=_=>{createCanvas(600, 600);noStroke();background(0)}
draw=_=>{translate(w=300,w);r=w;while(r--){u=x;v=y;a=b=-2;c=-1.2;d=2;
x=sin(a*v)-cos(b*u);y=sin(c*u)-cos(d*v);fill(0,128,w,99);circle(map(x,-2,2,-250,250), map(y,-2,2,-250,250), 1)}}

